const $=id=>document.getElementById(id),canvas=root.querySelector('canvas'),STORE='board3-zombies-v2';let s=fresh(PREFABS[0].counts,'close'),chosen='humans',speed=1,saveError='',raf=0,last=0,acc=0,saveClock=0;
