const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setClearColor(0,0);renderer.outputColorSpace=T.SRGBColorSpace;
const scene=new T.Scene(),camera=new T.OrthographicCamera();camera.position.set(5,7,9);camera.lookAt(.8,.3,0);scene.add(new T.HemisphereLight(0xfff4d9,0x374537,2.5));const sun=new T.DirectionalLight(0xffe4b0,3);sun.position.set(-6,12,5);scene.add(sun);
const land=new T.Group(),figures=new T.Group(),overlays=new T.Group();scene.add(land,figures,overlays);const materials=new Map();function mat(color){if(!materials.has(color))materials.set(color,new T.MeshStandardMaterial({color,roughness:1}));return materials.get(color);}
function mesh(g,color,parent,x=0,y=0,z=0){const m=new T.Mesh(g,mat(color));m.position.set(x,y,z);parent.add(m);return m;}
function box(w,h,d,color,parent,x,y,z){return mesh(new T.BoxGeometry(w,h,d),color,parent,x,y,z);}
function sphere(r,color,parent,x,y,z){return mesh(new T.IcosahedronGeometry(r,1),color,parent,x,y,z);}
const pos=t=>({x:Math.sqrt(3)*(t.q+t.r/2),z:1.5*t.r});
function clear(g){while(g.children.length){const m=g.children[0];m.traverse(o=>{o.geometry?.dispose();if(o.isLine)o.material?.dispose();});g.remove(m);}}
function person(parent,color,zombie=false,weapon=false){const g=new T.Group();parent.add(g);box(.25,.42,.25,color,g,0,.57,0);box(.11,.37,.12,'#343f32',g,-.1,.19,0);box(.11,.37,.12,'#343f32',g,.1,.19,0);sphere(.22,zombie?'#97b67c':'#e8bc8b',g,0,.99,0);box(.36,.12,.3,zombie?'#617044':'#704d34',g,0,1.14,-.02);const arm=box(.1,.38,.11,color,g,-.22,.61,zombie?.13:0);arm.rotation.x=zombie?-.9:.1;box(.1,.38,.11,color,g,.22,.61,zombie?.13:0);for(const x of [-.08,.08])box(.045,.045,.035,zombie?'#ffcc55':'#263d34',g,x,1.02,.19);if(weapon){const blade=box(.055,.35,.025,'#e4e8db',g,.25,.65,.18);blade.rotation.x=.5;}return g;}
function tower(parent){box(.9,1.65,.9,'#8a9281',parent,0,.83,0);box(1.2,.2,1.2,'#d2c39b',parent,0,1.65,0);for(const x of [-.47,0,.47])for(const z of [-.47,.47])box(.23,.3,.23,'#b1b59d',parent,x,1.9,z);box(.25,.55,.03,'#303e32',parent,0,.5,.46);const a=person(parent,'#d4ad63');a.position.set(0,1.77,0);const bow=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3(.34,2.95,.1),new T.Vector3(.52,2.7,.1),new T.Vector3(.34,2.4,.1)]),new T.LineBasicMaterial({color:0xdec58f}));parent.add(bow);}
function house(parent){box(1.2,.9,.95,'#d0bc8d',parent,0,.45,0);const roof=mesh(new T.ConeGeometry(1, .65,4),'#865b4c',parent,0,1.2,0);roof.rotation.y=Math.PI/4;box(.3,.55,.04,'#273d33',parent,0,.3,.5);box(.2,.23,.04,'#ffd47b',parent,-.37,.56,.5);box(.17,.23,.04,'#ffd47b',parent,.37,.56,.5);box(.17,.7,.2,'#776a55',parent,.37,1.24,-.2);}
const picks=[];
function platform(parent,type){mesh(new T.CylinderGeometry(.96,.96,.22,6),type==='zombies'?'#8e9676':'#aab382',parent,0,-.11,0);for(let i=0;i<5;i++)box(.035,.1,.035,'#d2c38e',parent,Math.sin(i*2)*.72,.05,Math.cos(i*2)*.72);if(type==='humans'){if(s.counts.archers){const g=new T.Group();parent.add(g);g.position.set(-.25,0,-.18);g.scale.setScalar(.45);tower(g);/* Static tower archer removed: actors are rendered from model. */const statue=g.children.find(c=>c.type==='Group');if(statue){clear(statue);g.remove(statue);}const bow=g.children.find(c=>c.type==='Line');if(bow){bow.geometry.dispose();g.remove(bow);}}if(s.counts.peasants){const h=new T.Group();parent.add(h);h.scale.setScalar(.42);h.position.set(.36,0,-.15);house(h);}}else{for(let i=0;i<3;i++){box(.16,.28,.1,'#c0c3a7',parent,(i-1)*.35,.14,-.3);sphere(.08,'#c0c3a7',parent,(i-1)*.35,.28,-.3);}}}
function rebuild(){clear(land);picks.length=0;for(const c of CELLS){const t=s.tiles.find(t=>t.q===c.q),p=pos(c),g=new T.Group();g.position.set(p.x,0,p.z);land.add(g);if(t){platform(g,t.type);if(s.phase==='placing'){const n=t.type==='humans'?s.counts.archers+s.counts.peasants:s.counts.zombies;for(let i=0;i<n;i++){const archer=t.type==='humans'&&i<s.counts.archers,a=person(g,archer?'#bd8850':t.type==='humans'?'#d2bb83':'#67805a',t.type==='zombies');a.scale.setScalar(.46);a.position.set((i%4-1.5)*.25,archer?.85:0,Math.floor(i/4)*.24+.1);}}}else{const tile=mesh(new T.CylinderGeometry(.96,.96,.035,6),'#b7c3ad',g,0,-.17,0);tile.userData.cell=c;picks.push(tile);}}draw();}
const ray=new T.Raycaster();canvas.addEventListener('pointerup',e=>{if(s.phase!=='placing')return;const rect=canvas.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hit=ray.intersectObjects(picks)[0];if(hit)act(()=>put(hit.object.userData.cell.q===0?'humans':'zombies'));});
function put(type){place(s,type,type==='humans'?0:1,0);chosen=hand(s)[0]||null;save();rebuild();sync();if(s.phase==='intro')$('ztools').hidden=true;wake();return read();}
function act(fn){try{const result=fn();sync();draw();window.RanchView?.changed();return result;}catch(e){$('zstatus').textContent=e.message;}}
function prepare(counts,id='custom'){validate(counts);const rev=s.revision;s=fresh(counts,id);s.revision=rev+1;forecast=simulate(counts);chosen='humans';save();rebuild();sync();return read();}
function reset(){return prepare(s.counts,s.prefab);}
function pause(value){s.paused=value;s.revision++;save();sync();wake();return read();}
function advance(seconds){const was=s.paused;s.paused=false;step(s,seconds);s.paused=was;save();sync();draw();return read();}
for(const p of PREFABS){const b=document.createElement('button');b.textContent=p.name;b.dataset.prefab=p.id;b.title=p.note;b.onclick=()=>act(()=>prepare(p.counts,p.id));$('zprefabs').append(b);}
function randomPrefab(difficulty=$('zdifficulty').value){const pool=RANDOM_POOLS[difficulty];if(!pool)throw Error('Unknown difficulty');const choices=pool.filter(p=>p.id!==s.prefab),p=choices[Math.floor(Math.random()*choices.length)];$('zdifficulty').value=difficulty;return prepare(p.counts,p.id);}
const randomButton=document.createElement('button');randomButton.textContent='⚄ Random';randomButton.onclick=()=>act(randomPrefab);$('zprefabs').append(randomButton);
function preview(type){const previewScene=new T.Scene();previewScene.add(new T.HemisphereLight(0xfff4d9,0x374537,3));const light=new T.DirectionalLight(0xffe4b0,3);light.position.set(-3,7,5);previewScene.add(light);const g=new T.Group();previewScene.add(g);platform(g,type);const n=type==='humans'?s.counts.archers+s.counts.peasants:s.counts.zombies;for(let i=0;i<n;i++){const archer=type==='humans'&&i<s.counts.archers,a=person(g,archer?'#bd8850':type==='humans'?'#d2bb83':'#67805a',type==='zombies');a.scale.setScalar(.42);a.position.set((i%4-1.5)*.25,archer?.8:0,(Math.floor(i/4))*.24+.15);}const pc=new T.OrthographicCamera(-1.4,1.4,1.1,-1.1,.1,30);pc.position.set(3,4,5);pc.lookAt(0,.3,0);renderer.setSize(240,160,false);renderer.render(previewScene,pc);const url=canvas.toDataURL('image/png');clear(g);resize();return url;}
let previousCards='';
function sync(){const c=s.counts;for(const k of ['archers','peasants','zombies'])if(document.activeElement!==$('z'+k))$('z'+k).value=c[k];for(const b of $('zprefabs').children)b.setAttribute('aria-pressed',String(b.dataset.prefab===s.prefab));const fp=JSON.stringify([c,s.tiles.map(t=>t.type)]);if(fp!==previousCards){previousCards=fp;$('zhand').replaceChildren();for(const type of ['humans','zombies']){const placed=s.tiles.some(t=>t.type===type),b=document.createElement('button');b.className='zcard';b.disabled=placed;b.innerHTML=`<img alt="${type==='humans'?'Player tower and defenders':'Zombie group'} miniature hex" src="${preview(type)}"><strong>${type==='humans'?'Players':'Zombies'}</strong><small>${type==='humans'?`${c.archers} archers · ${c.peasants} peasants`:`${c.zombies} zombies`}</small><span>${placed?'✓ Placed':`＋ Place ${type==='humans'?'players':'zombies'}`}</span>`;b.onclick=()=>act(()=>put(type));$('zhand').append(b);}}
$('zforecast').textContent=`${s.prefab==='custom'?'Custom forecast':'Pre-simulated'} · ${forecast.outcome==='won'?'Player victory':'Zombie victory'} · ${forecast.survivors} survivor${forecast.survivors===1?'':'s'} · ${forecast.seconds}s${forecast.rebirths?` · ${forecast.rebirths} rebirths`:''}`;
$('zpause').disabled=!['battle','intro'].includes(s.phase);$('zpause').textContent=s.paused?'▶ Resume':'Ⅱ Pause';$('zstep').disabled=!['battle','intro'].includes(s.phase);
$('zstatus').textContent=saveError||(s.phase==='placing'?s.tiles.length?'Place the other card. The fight starts automatically.':'Two cards. One encounter. Choose a prefab in the drawer.':`${s.actors.filter(a=>a.kind==='human'&&a.hp>0).length} living · ${s.kills} defeated · ${s.rebirths} risen${s.paused?' · Paused':''}`);
$('zmetrics').textContent=`${s.phase} · ${s.time.toFixed(1)}s · ${s.tiles.length}/2 cards placed · Saved in this browser`;
$('zcinema').hidden=!s.cutscene;$('zcinema').querySelector('strong').textContent=s.cutscene||'';$('zcinema').querySelector('small').textContent=s.phase==='won'?`${s.kills} defeated · ${s.actors.filter(a=>a.kind==='human'&&a.hp>0).length} survivors`:s.phase==='intro'?'Both cards placed. Hold the line.':s.phase==='lost'?'The dead inherit the battlefield.':'Watch the fallen return.';}
function label(text,p,y,small=false){const v=new T.Vector3(p.x,y,p.z).project(camera),el=document.createElement('div');el.className='zlabel';el.style.left=(v.x+1)*canvas.clientWidth/2+'px';el.style.top=(1-v.y)*canvas.clientHeight/2+'px';if(small){const t=document.createElement('small');t.textContent=text;el.append(t);}else el.textContent=text;$('zlabels').append(el);return el;}
function line(a,b,color){overlays.add(new T.Line(new T.BufferGeometry().setFromPoints([a,b]),new T.LineBasicMaterial({color})));}
const actorVisuals=new Map();
function draw(){for(const [id,item] of actorVisuals){const a=s.actors.find(a=>a.id===id);if(!a||a.hp<=0||a.shelteredUntil){figures.remove(item.g);clear(item.g);actorVisuals.delete(id);}}clear(overlays);$('zlabels').replaceChildren();for(const c of CELLS)if(!s.tiles.some(t=>t.q===c.q))label(c.q===0?'＋ PLAYERS':'＋ ZOMBIES',pos(c),.05,true);for(const a of s.actors){const p=pos(a);if(a.hp<=0){if(s.time-a.deadAt<1.6)label('💀',p,.6+(s.time-a.deadAt)*.2);continue;}if(a.shelteredUntil){label('🏠 Hiding → 🔪',p,1,true);continue;}let visual=actorVisuals.get(a.id);const signature=a.kind+!!a.weapon;if(visual?.signature!==signature){if(visual){figures.remove(visual.g);clear(visual.g);}visual={signature,g:person(figures,a.role==='archer'?'#bd8850':a.kind==='human'?'#d2bb83':'#67805a',a.kind==='zombie',a.weapon)};visual.g.scale.setScalar(.46);actorVisuals.set(a.id,visual);}const g=visual.g,y=a.role==='archer'?.85:0;g.position.set(p.x,y,p.z);if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&s.phase==='battle'&&!s.paused)g.rotation.z=Math.sin(s.time*7+a.offset)*.04;if($('zhealth').checked){const el=label(a.role==='archer'?'🏹':a.weapon?'🔪':'',p,y+.7,true),bar=document.createElement('span');bar.className='zhealth';bar.innerHTML=`<i style="width:${a.hp/3*100}%"></i>`;el.append(bar);}}
if(s.phase==='placing')for(const t of s.tiles)label(t.type==='humans'?'PLAYERS READY':'ZOMBIES READY',pos(t),1.6,true);
if($('zrange').checked&&s.tiles.some(t=>t.type==='humans')){const pts=[];for(let i=0;i<=64;i++)pts.push(new T.Vector3(Math.cos(i*Math.PI/32)*3.46,.03,Math.sin(i*Math.PI/32)*3));overlays.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:0xb18842})));}
for(const e of s.effects){const p=pos(e);if(e.kind==='arrow'&&s.time-e.at<.3){const to=pos(e.to);line(new T.Vector3(p.x,1.2,p.z),new T.Vector3(to.x,.35,to.z),0xc69037);}else if(['rebirth','knife'].includes(e.kind))label(e.kind==='rebirth'?'🧟':'🔪',p,.8+(s.time-e.at)*.3);else if(e.kind==='hit'&&s.time-e.at<.2)label('✦',p,.5);}
renderer.render(scene,camera);}
function resize(){const w=root.clientWidth,h=root.clientHeight,aspect=w/h,vertical=aspect<.8?4.8/aspect:4.8;camera.left=-vertical*aspect/2;camera.right=vertical*aspect/2;camera.top=vertical/2;camera.bottom=-vertical/2;camera.updateProjectionMatrix();renderer.setSize(w,h,false);draw();}window.addEventListener('resize',resize);
function frame(now){raf=0;if(document.hidden||s.paused||!['battle','intro'].includes(s.phase))return;const dt=Math.min((now-last)/1000,.1);last=now;acc+=dt;if(acc>=1/30){step(s,Math.min(acc*speed,1));saveClock+=acc;acc=0;if(saveClock>=1){save();window.RanchView?.changed();saveClock=0;}sync();draw();}if(['battle','intro'].includes(s.phase))raf=requestAnimationFrame(frame);else{save();window.RanchView?.changed();}}
function wake(){if(!raf&&!document.hidden&&!s.paused&&['battle','intro'].includes(s.phase)){last=performance.now();raf=requestAnimationFrame(frame);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;save();}else wake();});window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);save();renderer.dispose();});
function read(){return {scenario:'zombies',version:2,randomDifficulty:$('zdifficulty').value,revision:s.revision,phase:s.phase,time:s.time,paused:s.paused,counts:s.counts,prefab:s.prefab,forecast,prefabs:PREFABS.map(p=>({...p,result:forecasts[p.id]})),hand:hand(s),connected:connected(s),tiles:s.tiles,actors:s.actors,kills:s.kills,rebirths:s.rebirths,cutscene:s.cutscene,storageScope:'this-browser; separate from sandbox',saveError,speed,overlays:{range:$('zrange').checked,health:$('zhealth').checked},warnings:saveError?[saveError]:[]};}
function overlay(kind,enabled){$({range:'zrange',health:'zhealth'}[kind]).checked=enabled;s.revision++;draw();return read();}
function rate(value){speed=value;$('zspeed').value=String(value);s.revision++;return read();}
const schema=(properties={},required=[])=>({type:'object',properties,required,additionalProperties:false});
window.RanchView?.register('zombies',read,()=>draw());window.RanchActions?.register('zombies',{revision:()=>s.revision,read,unavailable:action=>action==='place'&&s.phase!=='placing'?'Battle already started':null,actions:{random:{description:'Choose a pre-simulated matchup at the requested difficulty',schema:schema({difficulty:{type:'string',enum:['easy','medium','hard','death']}},['difficulty']),run:a=>randomPrefab(a.difficulty)},prefab:{description:'Load a pre-simulated pair of encounter cards; resets encounter',schema:schema({id:{type:'string',enum:PREFABS.map(p=>p.id)}},['id']),run:a=>{const p=PREFABS.find(p=>p.id===a.id);return prepare(p.counts,p.id);}},counts:{description:'Prepare custom cards and simulate forecast; resets encounter',schema:schema({archers:{type:'integer',minimum:0,maximum:4},peasants:{type:'integer',minimum:0,maximum:6},zombies:{type:'integer',minimum:1,maximum:12}},['archers','peasants','zombies']),run:a=>prepare(a)},place:{description:'Place Players or Zombies; second placement starts combat automatically',schema:schema({type:{type:'string',enum:['humans','zombies']}},['type']),run:a=>put(a.type)},pause:{description:'Pause or resume',schema:schema({paused:{type:'boolean'}},['paused']),run:a=>pause(a.paused)},step:{description:'Advance simulation',schema:schema({seconds:{type:'number',minimum:.05,maximum:1}},['seconds']),run:a=>advance(a.seconds)},reset:{description:'Replay current matchup',schema:schema(),run:reset},overlay:{description:'Toggle simulation overlay',schema:schema({kind:{type:'string',enum:['range','health']},enabled:{type:'boolean'}},['kind','enabled']),run:a=>overlay(a.kind,a.enabled)},speed:{description:'Set playback speed',schema:schema({value:{type:'number',enum:[.35,1,2]}},['value']),run:a=>rate(a.value)}}});
$('znav-open').onclick=()=>{$('znav').hidden=!$('znav').hidden;};$('znav-close').onclick=()=>{$('znav').hidden=true;};$('ztools-open').onclick=()=>{$('ztools').hidden=!$('ztools').hidden;window.RanchView?.changed();};$('zclose').onclick=()=>{$('ztools').hidden=true;window.RanchView?.changed();};$('zreset').onclick=()=>act(reset);$('zpause').onclick=()=>act(()=>pause(!s.paused));$('zstep').onclick=()=>act(()=>{pause(true);return advance(.25);});$('zcounts').onclick=()=>act(()=>prepare(Object.fromEntries(['archers','peasants','zombies'].map(k=>[k,Number($('z'+k).value)]))));$('zspeed').onchange=()=>act(()=>rate(Number($('zspeed').value)));for(const [kind,id]of Object.entries({range:'zrange',health:'zhealth'}))$(id).onchange=()=>act(()=>overlay(kind,$(id).checked));window.addEventListener('keydown',e=>{if(e.key==='Escape'){$('ztools').hidden=true;$('znav').hidden=true;}});
